/*
 * Structural styles for the copy-owned document components. Consuming
 * applications supply typography and font faces through their own stylesheet.
 */

@import "tailwindcss";

/*
 * The classes the `typography` token can produce.
 *
 * A document's `scale` and `flow` step the size, leading, and gap classes the
 * components carry, and the stepped names are built at render time, so no
 * source file contains them for Tailwind to find. Without this, the default
 * PDF engine would honour `leading-loose` while the browser had no rule for
 * it, and the preview and the PDF would stop being one document. Listing the
 * whole verified scale here, rather than only what the shipped components
 * reach, keeps a copy owner's own literal on the same footing.
 */
@source inline("text-{xs,sm,base,lg,xl,2xl,3xl,4xl,5xl,6xl,7xl,8xl,9xl}");
@source inline("leading-{none,tight,snug,relaxed,loose,{0..16},{0.5,1.5,2.5}}");
@source inline("gap-{{0..24},{0.5,1.5,2.5}} gap-x-{{0..24},{0.5,1.5,2.5}} gap-y-{{0..24},{0.5,1.5,2.5}}");
/*
 * A value that is left to right whatever the document is.
 *
 * A phone number in E.164 and an identification number are runs of digits and
 * punctuation, which the bidirectional algorithm gives no direction of their
 * own: inside a right-to-left paragraph it resolves them against the paragraph
 * and moves the leading `+` to the visual end. `isolate` takes the run out of
 * the surrounding paragraph's ordering, which is what puts it back. `Field`
 * applies it only where the document runs right to left, and it carries the
 * same rule as an inline style for a renderer that reads no stylesheet of ours.
 */
.paradoc-ltr-isolate {
  direction: ltr;
  unicode-bidi: isolate;
}
